function toSides(sections){
  var names = Object.keys(sections)
  var left = 0
  var right = 1
  var sides = {
    'left': [sections[names[left]]()],
    'right': [sections[names[right]]()],
  }

  for (let i = 1; i < names.length - 1; i++ ) {
    left  = left + 2 * (i%2)
    right = right + 2 * ((1+i)%2)
    sides['left'].push(sections[names[left]]())
    sides['right'].push(sections[names[right]]())
  }
  return sides
}

var sides = toSides(sections)
