// 🟢 FIX: This loop automatically generates the correct 5 overlapping transition zones
function toSides(sections) {
  const names = Object.keys(sections);
  const left = [];
  const right = [];

  // 5 steps total for 6 tracks: 0 to 4
  for (let i = 0; i < names.length - 1; i++) {
